_file_map = {

    "categorize.baml": "class TagOption {\n  slug string\n  description string? @description(\"When to apply this tag\")\n}\n\nclass CategorizeAndTagResult {\n  categories ArticleCategory[] @description(\"1-2 categories\")\n  kind ArticleKind\n  tags string[] @description(\"1-3 slugs copied verbatim from the vocabulary; most relevant first\")\n}\n\nclass ClassifyKindResult {\n  kind ArticleKind\n}\n\nfunction CategorizeAndTag(title: string, content: string, vocabulary: TagOption[]) -> CategorizeAndTagResult {\n  client Nvidia\n  prompt #\"\n    {{ _.role(\"system\") }}\n    You are an editor and taxonomist for a developer news digest. Your readers are tech-savvy but busy. You assign topic tags from a fixed controlled vocabulary and never invent tags.\n\n    {{ _.role(\"user\") }}\n    Classify and tag this article.\n\n    Title: {{ title }}\n\n    Content:\n    {{ content }}\n\n    1. Assign 1-2 categories.\n    2. Assign a kind.\n    3. Assign 1-3 tags from the vocabulary below, most relevant first. Pick the smallest set that captures what the article is actually about - do not pad to three. Use slugs from the vocabulary ONLY, copied exactly as written.\n\n    Category definitions:\n    - Models: New model releases, benchmarks, evals, model cards, model comparisons\n    - Dev: Repos, tools, product launches, developer blogs, tutorials, how-tos, fine-tuning guides, deployment recipes, infrastructure updates\n    - Research: Papers, breakthroughs, novel techniques with practical implications\n\n    Kind definitions:\n    - Repo: GitHub or GitLab repository\n    - Paper: Academic paper, preprint, or long-form technical report\n    - Model: Model card or model release page (e.g. HuggingFace)\n    - Blog: Developer blog post, tutorial, how-to, or opinion piece\n    - Product: Product launch page or product website\n    - Announcement: Official release post from a major AI lab (OpenAI, Anthropic, Google, Meta, Mistral, etc.)\n\n    Tag vocabulary — use these slugs ONLY, copied exactly as written:\n    {% for t in vocabulary %}\n    - {{ t.slug }}{% if t.description %}: {{ t.description }}{% endif %}\n    {% endfor %}\n\n    {{ ctx.output_format }}\n  \"#\n}\n\nfunction ClassifyKind(title: string, url: string) -> ClassifyKindResult {\n  client Nvidia\n  prompt #\"\n    {{ _.role(\"system\") }}\n    You are a technical librarian who classifies AI developer content by format.\n\n    {{ _.role(\"user\") }}\n    Classify this article's kind.\n\n    Title: {{ title }}\n    URL: {{ url }}\n\n    Kind definitions:\n    - Repo: GitHub or GitLab repository\n    - Paper: Academic paper, preprint, or long-form technical report\n    - Model: Model card or model release page (e.g. HuggingFace)\n    - Blog: Developer blog post, tutorial, how-to, or opinion piece\n    - Product: Product launch page or product website\n    - Announcement: Official release post from a major AI lab (OpenAI, Anthropic, Google, Meta, Mistral, etc.)\n\n    {{ ctx.output_format }}\n  \"#\n}\n\ntest categorize_and_tag_basic {\n  functions [CategorizeAndTag]\n  args {\n    title \"Anthropic releases Claude 4\"\n    content \"Anthropic today launched Claude 4, a new flagship model. It features improved reasoning, a 1M-token context window, and native tool use. The model is available via API and Claude.ai starting today.\"\n    vocabulary [\n      {\n        slug \"models\"\n        description \"new model releases, benchmarks, evals\"\n      }\n      {\n        slug \"agents\"\n        description \"autonomous agents: reasoning loops, planning\"\n      }\n    ]\n  }\n}\n",
    "clients.baml": "// The provider caps how many requests may be in flight at once, far below its\n// per-minute quota: measured 2026-09-03, 5 parallel calls all answered while 10\n// returned 429 in ~90ms with x-ratelimit-remaining still at 1980/2000, and the\n// cap refills within ~10s. So a 429 here means \"too many at once\", never \"out\n// of budget\", and waiting is the correct response. Without this policy those\n// bursts fell through to the fallback client instead.\nretry_policy Burst {\n  max_retries 4\n  strategy {\n    type exponential_backoff\n    delay_ms 500\n    multiplier 2\n    max_delay_ms 8000\n  }\n}\n\n// Second in line as of 2026-09-03, replacing NVIDIA's gpt-oss-120b, which\n// reached end of life that morning and answered every call with 410 Gone. The\n// slot had been dead weight for hours before anyone noticed, because a fallback\n// only speaks up when the primary fails.\n//\n// Still NVIDIA NIM, deliberately: a fallback on Ministral's own provider would\n// share its rate limiter, and the failure this slot exists to absorb is\n// Infomaniak refusing a burst. A second provider is the whole point.\n//\n// Measured 2026-09-03 on a SelectProductLink-shaped prompt: 1.5-6.8s across\n// sequential calls, all answering with clean JSON and the right pick — no sign\n// of the 52-285s latency that made gpt-oss-120b unusable, though that was a\n// property of the endpoint under load, so it is worth re-measuring if runs\n// start crawling. Past 8 parallel calls NIM starts returning 503; the retry\n// policy covers those.\n//\n// Infomaniak's Qwen3.5-397B was the other candidate and judged just as well,\n// but it is a reasoning model: it spends its budget in a `reasoning` field and\n// emits an EMPTY content string if it runs out before it stops thinking (427\n// completion tokens for a two-element array). That needs a large explicit\n// max_tokens to be safe, on top of sharing Ministral's limiter.\nclient<llm> Nemotron {\n  provider openai-generic\n  retry_policy Burst\n  options {\n    base_url \"https://integrate.api.nvidia.com/v1\"\n    api_key env.NVIDIA_NIM_API_KEY\n    model \"nvidia/nemotron-3-super-120b-a12b\"\n    timeout 120\n  }\n}\n\n// Primary as of 2026-08-06: fast and reliable, lower quality. Chosen for\n// throughput — it answers in 2-3s where gpt-oss was taking minutes. See the\n// variance warning on the Nvidia wrapper below before moving it back.\nclient<llm> Ministral {\n  provider openai-generic\n  retry_policy Burst\n  options {\n    base_url \"https://api.infomaniak.com/2/ai/7/openai/v1\"\n    api_key env.IK_AI_KEY\n    model \"mistralai/Ministral-3-14B-Instruct-2512\"\n    timeout 120\n  }\n}\n\n// The name every function already references. A fallback wrapper: try Ministral\n// first, drop to Nemotron if it fails. Renaming would mean editing all 12\n// `client Nvidia` sites for no gain, so the name stays — and with Nemotron in\n// the second slot it is at least half true again.\n//\n// A Gemini Flash client sat third here until 2026-09-03, when the run that\n// needed it got 400 FAILED_PRECONDITION \"User location is not supported for\n// the API use\" - the Google AI API does not serve the prod VPS's region, so\n// the last resort had never been able to answer. Removed rather than left in\n// place: a client that always fails is not a fallback, it just hides how thin\n// the chain really is. A replacement has to be reachable from the box.\n//\n// KNOWN COST OF THIS ORDER, for ScoreArticles specifically: Ministral-3-14B\n// judged with ±15 run-to-run variance on identical input and intermittently\n// returned fewer results than it was given, which apply_scores reads as\n// score 0 — i.e. a silent reject. gpt-oss-120b led for that reason until its\n// provider latency made full runs impossible. Traded accuracy for a run that\n// finishes. Nemotron looks like the better judge and is worth trying in front\n// for scoring, but that swap needs a full score_articles pass measured end to\n// end before it lands. See plans/scoring-recalibration.md.\nclient<llm> Nvidia {\n  provider fallback\n  options {\n    strategy [Ministral, Nemotron]\n  }\n}\n",
    "discover.baml": "// Batched relevance classifier for the Substack discovery crawler.\n// One LLM call judges many candidate profiles at once (see ScoreArticles for\n// the array-in/array-out batching pattern). Classification runs on cheap\n// metadata (name + description) BEFORE any per-profile post fetch, and gates\n// both DB insertion and whether the crawler recurses into that profile.\n\nclass ProfileInput {\n  handle string @description(\"Substack owner handle, echoed back in the verdict\")\n  name string @description(\"Publication name\")\n  description string? @description(\"Publication hero text and/or author bio, if known\")\n}\n\nclass ProfileVerdict {\n  handle string @description(\"Must exactly match the input handle\")\n  isAiRelated bool\n  confidence int @description(\"0-100 confidence that AI/ML/LLMs is the PRIMARY focus\")\n}\n\nfunction ClassifyProfiles(profiles: ProfileInput[]) -> ProfileVerdict[] {\n  client Nvidia\n  prompt #\"\n    {{ _.role(\"system\") }}\n    You curate sources for a developer-focused AI news platform. For each Substack\n    publication, decide whether artificial intelligence is its PRIMARY subject:\n    AI/ML/LLMs, foundation models, AI engineering, AI products, or AI research.\n\n    Mark isAiRelated = true ONLY when AI is clearly the main topic. Mark false for\n    general tech, productivity, marketing, business, crypto, politics, lifestyle, or\n    publications that merely mention AI in passing. When the signal is thin (sparse\n    description, generic name), lean false and assign low confidence - the crawler\n    prunes everything you reject, so false positives pollute the whole subtree.\n\n    {{ _.role(\"user\") }}\n    Classify every profile. Echo each handle back EXACTLY as given.\n\n    {% for p in profiles %}\n    {{ loop.index }}. handle={{ p.handle }} | {{ p.name }}{% if p.description %} — {{ p.description }}{% endif %}\n    {% endfor %}\n\n    {{ ctx.output_format }}\n  \"#\n}\n",
    "extract_items.baml": "// Newsletter extraction.\n//\n// A newsletter reports two kinds of thing worth ingesting, and they need\n// different URL resolution:\n//\n// - Product: a named launch (model, tool, SDK). Its canonical URL is the\n//   vendor's own page, which the email rarely links to directly, so the URL is\n//   rediscovered by web search (SelectProductLink) rather than trusted from the\n//   email. This replaced the per-newsletter tracking-URL decoders.\n// - Article: a blog post, essay, paper, or write-up. Here the link IS the\n//   subject — there is nothing to search for, and a search would land on some\n//   other page about the same topic. Its href is kept and followed instead\n//   (see ``_resolve_article`` in pipeline/sources/email.py), which turns a\n//   tracking redirect into the real destination.\n//\n// Hence NewsletterItem.url: the model must copy an article's href verbatim\n// even though it is usually a redirect, because following it is exactly how\n// the real URL is recovered.\n\nenum NewsletterItemKind {\n  Product  // A named product, tool, model, SDK, dataset, or launch\n  Article  // A blog post, essay, paper, guide, or write-up\n}\n\nclass NewsletterItem {\n  kind NewsletterItemKind\n  name string @description(\"Product name, or the article's title\")\n  description string @description(\"Concise phrase: what it is and does, usable verbatim as a web search query\")\n  url string? @description(\"For an Article, the href of its link, copied verbatim including any tracking redirect. Omit for a Product.\")\n}\n\nfunction ExtractItems(newsletterText: string) -> NewsletterItem[] {\n  client Nvidia\n  prompt #\"\n    {{ _.role(\"system\") }}\n    You extract the AI/tech items a newsletter is reporting on: named products, and the articles it links to. Work only from the text; never invent items that are not mentioned.\n\n    {{ _.role(\"user\") }}\n    Below is the text of a newsletter email. Links appear as [anchor text](url).\n\n    Identify every distinct item the newsletter reports as news, and classify each:\n\n    - Product — a named product, tool, model, SDK, dataset, or launch a reader could go use. Judge it by the words, not the link: its URL is looked up separately, so do NOT return a url for a Product.\n    - Article — a blog post, essay, paper, guide, benchmark write-up, or analysis the newsletter is pointing at. For these the link is the subject, so ALWAYS return its url, copied verbatim from the text — including tracking redirects, which are followed later to recover the real destination. An item with no link is not an Article.\n\n    For each item return:\n    - kind: Product or Article\n    - name: the exact product name, or the article's title\n    - description: a concise phrase describing what it is and does, suitable as a web search query\n    - url: the article's href (Article only)\n\n    A single story often yields one item, not two: if a link is the vendor's own announcement of a named launch, return it as a Product. Return an Article when the piece itself is the point — someone's write-up, teardown, guide, or opinion.\n\n    INCLUDE only real, named launches and substantive articles a reader could go use or read.\n\n    IGNORE:\n    - the author's intro letter and personal commentary\n    - sponsor blurbs, advertisements, \"brought to you by\", upgrade / subscribe / manage-preferences prompts\n    - social-media embeds (an @handle with like / repost / reply counts) and the newsletter's own social links\n    - section headers, navigation, and unsubscribe links\n    - job postings\n\n    Newsletter text:\n    {{ newsletterText }}\n\n    If the text names no qualifying items, return an empty list.\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n// Notability gate: trims the extracted list to the items actually worth\n// resolving, so we don't spend a web search on every incremental SDK bump.\n// Returns the 1-based indices of the items to KEEP.\nfunction SelectNotableItems(items: NewsletterItem[]) -> int[] {\n  client Nvidia\n  prompt #\"\n    {{ _.role(\"user\") }}\n    Below is a numbered list of items a newsletter mentioned. Return the numbers of the ones that are NOTABLE enough to feature in an AI-news aggregator.\n\n    KEEP an item if it is distinct, real, and individually newsworthy: new models, significant new products or platforms, notable agents/tools, major releases, and articles with real substance — technical write-ups, benchmarks, teardowns, engineering posts, or arguments a developer would want to read.\n\n    DROP:\n    - minor or incremental items: small SDK/utility bumps, niche helper libraries, design skills, config tweaks\n    - vague or marketing-only entries with no concrete product behind them\n    - listicles, SEO filler, press-release rewrites, and thin news blurbs that only restate an announcement\n    - duplicates or sub-features of another item in the list\n\n    Items:\n    {% for item in items %}\n    {{ loop.index }}. [{{ item.kind }}] {{ item.name }} — {{ item.description }}\n    {% endfor %}\n\n    Return only the numbers to keep, as a JSON array of integers. If none qualify, return [].\n\n    {{ ctx.output_format }}\n  \"#\n}\n\nclass SearchCandidate {\n  title string\n  url string\n  snippet string\n}\n\nclass ProductLinkChoice {\n  index int @description(\"1-based index of the best first-party result, or 0 if none qualifies\")\n  confidence float @description(\"0.0 - 1.0\")\n}\n\n// Picks the best canonical URL for a product among search candidates, biased\n// hard toward the official / first-party source and away from social posts and\n// SEO/aggregator pages. Returns index 0 when nothing is clearly the product.\n// Products only — an article already carries its own link.\nfunction SelectProductLink(\n  productName: string,\n  productDescription: string,\n  candidates: SearchCandidate[]\n) -> ProductLinkChoice {\n  client Nvidia\n  prompt #\"\n    {{ _.role(\"user\") }}\n    A newsletter featured this item:\n      name: {{ productName }}\n      description: {{ productDescription }}\n\n    Web search returned these candidate results:\n    {% for c in candidates %}\n    {{ loop.index }}. {{ c.title }}\n       url: {{ c.url }}\n       snippet: {{ c.snippet }}\n    {% endfor %}\n\n    Pick the ONE candidate that is the canonical, first-party source for this exact product — its official site, product page, model card, repo, or the vendor's own announcement.\n\n    PREFER the official / first-party domain that matches the product or its maker.\n    REJECT (do not pick) when it is the best available:\n    - social-media posts (x.com, twitter.com, linkedin.com, reddit.com, threads, mastodon)\n    - videos (youtube.com)\n    - content-farm / SEO / generic aggregator or listicle pages that merely mention the product\n    - a DIFFERENT product that happens to share the name\n\n    Return the 1-based index of the best first-party result. If none of the candidates is clearly a first-party source for THIS product, return index 0.\n\n    {{ ctx.output_format }}\n  \"#\n}\n\ntest extract_items_basic {\n  functions [ExtractItems]\n  args {\n    newsletterText \"Headlines: [OpenAI ships GPT-5](https://sub.stack/redirect/2/abc), a new flagship model. Deep dive: [Why agent harnesses fail](https://stencil.so/blog/harness-playbook?utm_source=tldrai) walks through production agent design. Brought to you by Acme. [Unsubscribe](https://newsletter.com/unsub).\"\n  }\n}\n",
    "extract_links.baml": "class ExtractedLink {\n  title string\n  url string\n  snippet string @description(\"One-sentence description of the article\")\n}\n\nfunction ExtractLinks(emailHtml: string) -> ExtractedLink[] {\n  client Nvidia\n  prompt #\"\n    {{ _.role(\"system\") }}\n    You are a precise link extraction engine. You parse newsletter HTML and identify external article links while filtering out tracking, admin, and promotional URLs.\n\n    {{ _.role(\"user\") }}\n    You are given the HTML body of a newsletter email. Extract all article links that point to external news stories, blog posts, research papers, or product announcements.\n\n    For each article, return its title, URL, and a one-sentence snippet describing it.\n\n    IGNORE these types of links:\n    - Tracking/redirect URLs (e.g. links through email marketing platforms)\n    - Unsubscribe, manage preferences, or email settings links\n    - Social media profile links (twitter, linkedin, etc.)\n    - Links back to the newsletter's own homepage, archive index, or subscription page (but DO include article/post links hosted on the newsletter's domain - curated newsletters often host their own content)\n    - Sponsor/advertisement links\n    - Job posting links\n\n    RESOLVE redirect URLs: if a link is clearly a tracking redirect (contains /click, /track, utm_ params, etc.), try to extract the final destination URL from the href. Strip all UTM parameters from URLs.\n\n    Newsletter HTML:\n    {{ emailHtml }}\n\n    If no relevant article links are found, return an empty list.\n\n    {{ ctx.output_format }}\n  \"#\n}\n\ntest extract_links_basic {\n  functions [ExtractLinks]\n  args {\n    emailHtml \"Welcome to today's issue! [Read OpenAI's new paper](https://openai.com/papers/gpt-5). [Unsubscribe](https://newsletter.com/unsubscribe).\"\n  }\n}\n",
    "fix_titles.baml": "class TitleFix {\n  url string @description(\"The exact URL from the matching input article - copy verbatim\")\n  title string @description(\"Plain English title text on a single line. No markdown, no quotes, no leading source name or bracket tag. Max 12 words. Return the input title verbatim if it is already clear, specific, and informative.\")\n}\n\nfunction ImproveTitles(articles: ArticleInput[]) -> TitleFix[] {\n  client Nvidia\n  prompt #\"\n    {{ _.role(\"system\") }}\n    You are a technical editor. You write clear, informative article titles for an AI developer news platform.\n\n    Output rules (strict):\n    - For each input article, return one TitleFix whose `url` exactly matches that article's URL.\n    - The `title` field contains plain title text ONLY. Do NOT wrap it in quotes. Do NOT prefix it with \"[Source]\" or any source name. Do NOT include the URL.\n    - Write in English. Never emit any other language or script.\n    - No markdown. Do NOT wrap the title in ** or * or _ or backticks.\n    - One single line. No newlines, no braces, no brackets, no JSON.\n    - Every title must be a complete phrase. Never truncate mid-word or mid-sentence.\n    - Use only the snippet of the SAME article to inform the rewrite. Never blend information across articles.\n\n    {{ _.role(\"user\") }}\n    Decide for each article whether the existing title is already good. A good title is specific, informative, and technical/neutral in register - it tells a developer what the article is actually about.\n\n    - If the existing title is already good, return it verbatim.\n    - Otherwise rewrite it using only that article's snippet: specific, informative, between 3 and 12 words, technical/neutral register, no hype or filler.\n    - If the snippet is empty or too thin to write an accurate title from, return the existing title verbatim rather than inventing one.\n\n    {% for a in articles %}\n    --- Article {{ loop.index }} ---\n    url: {{ a.url }}\n    source: {{ a.source }}\n    current_title: {{ a.title }}\n    {% if a.snippet %}snippet: {{ a.snippet }}{% endif %}\n    {% endfor %}\n\n    {{ ctx.output_format }}\n  \"#\n}\n\ntest improve_titles_rewrite_short {\n  functions [ImproveTitles]\n  args {\n    articles [\n      {\n        url \"https://example.com/claude\"\n        title \"Claude 4\"\n        source \"HN\"\n        snippet \"Anthropic today released Claude 4, a new flagship model with improved reasoning and a 1M-token context window.\"\n      }\n    ]\n  }\n}\n\ntest improve_titles_keep_unchanged {\n  functions [ImproveTitles]\n  args {\n    articles [\n      {\n        url \"https://example.com/post\"\n        title \"Anthropic releases Claude 4 with 1M-token context window\"\n        source \"HN\"\n        snippet \"Anthropic today released Claude 4, a new flagship model with improved reasoning.\"\n      }\n    ]\n  }\n}\n\n// ─── Regression tests ───────────────────────────────────────────────────────\n// Real inputs from the production `article` table that produced corrupted\n// titles. Note the snippets are themselves already dirty (markdown bold,\n// stray CJK) — Summarize emitted them, and ImproveTitles copied the garbage\n// straight into the title. These assert the model no longer propagates it.\n//\n// Run: cd baml_src && baml-cli test\n\ntest regression_cjk_in_snippet {\n  functions [ImproveTitles]\n  args {\n    articles [\n      {\n        url \"https://x.com/TeksCreate/status/2075315553602814410\"\n        title \"GPT-5.6 agent workflows\"\n        source \"Aligned News\"\n        snippet #\"\n          GPT-5.6 focuses on supporting autonomous agents that operate for hours.\n          伊律(Meagle) this highlights durable workflows over raw benchmark score increases.\n          OpenAI had not previously publicized its agent capabilities as a key feature before now.\n        \"#\n      }\n    ]\n  }\n  @@assert(url_preserved, {{ this[0].url == \"https://x.com/TeksCreate/status/2075315553602814410\" }})\n  @@assert(no_markdown, {{ \"**\" not in this[0].title }})\n  @@assert(no_cjk, {{ \"伊\" not in this[0].title and \"律\" not in this[0].title }})\n  @@assert(single_line, {{ \"\\n\" not in this[0].title }})\n  @@assert(max_12_words, {{ this[0].title|split(\" \")|list|length <= 12 }})\n}\n\ntest regression_markdown_in_snippet {\n  functions [ImproveTitles]\n  args {\n    articles [\n      {\n        url \"https://www.therundown.ai/p/meta-sizes-up-gpt-5-5-with-watermelon\"\n        title \"Meta sizes up GPT-5.5 with Watermelon\"\n        source \"The Rundown AI\"\n        snippet #\"\n          Meta shares details on **Watermelon**, an internal GPT-5.5 benchmarking framework for ML experiments.\n          Frameworks like this test scalability, efficiency, and performance of large models.\n          Cursor Mobile also extends screenshot-to-bug-fix workflows for developers.\n        \"#\n      }\n    ]\n  }\n  @@assert(no_markdown, {{ \"**\" not in this[0].title and \"*\" not in this[0].title }})\n  @@assert(single_line, {{ \"\\n\" not in this[0].title }})\n  @@assert(no_json, {{ \"}\" not in this[0].title and \"]\" not in this[0].title }})\n  @@assert(max_12_words, {{ this[0].title|split(\" \")|list|length <= 12 }})\n}\n\n// Produced the truncated `**\"GPT-5.6` title in prod.\ntest regression_truncated_generation {\n  functions [ImproveTitles]\n  args {\n    articles [\n      {\n        url \"https://www.bensbites.com/p/grok-x-cursor\"\n        title \"Grok x Cursor\"\n        source \"Ben's Bites\"\n        snippet #\"\n          OpenAI updated ChatGPT with GPT-5.6 and a synthetic voice feature.\n          The changes include the ability to swap between voices in the free tier.\n          A new preview mode called 'Fable' introduces narrative-based interactions.\n        \"#\n      }\n    ]\n  }\n  @@assert(no_quote_wrapper, {{ '\"' not in this[0].title }})\n  @@assert(no_markdown, {{ \"**\" not in this[0].title }})\n  @@assert(complete_phrase, {{ this[0].title|split(\" \")|list|length >= 3 }})\n  @@assert(max_12_words, {{ this[0].title|split(\" \")|list|length <= 12 }})\n}\n\n// Produced the title with raw JSON (`}` / `]`) welded onto the end.\ntest regression_json_envelope_leak {\n  functions [ImproveTitles]\n  args {\n    articles [\n      {\n        url \"https://openai.com\"\n        title \"Build Week\"\n        source \"Aligned News\"\n        snippet #\"\n          SF developers can get live help and structured testing for frontier GPT-5.6 systems.\n          Local workshops guide them from concept to implementation.\n          The event offers hands-on access to AI system trials.\n        \"#\n      }\n    ]\n  }\n  @@assert(no_json, {{ \"}\" not in this[0].title and \"]\" not in this[0].title and \"{\" not in this[0].title }})\n  @@assert(single_line, {{ \"\\n\" not in this[0].title }})\n  @@assert(max_12_words, {{ this[0].title|split(\" \")|list|length <= 12 }})\n}\n\n// Thin snippet: the model must fall back to the original title, not invent one.\ntest regression_thin_snippet_keeps_original {\n  functions [ImproveTitles]\n  args {\n    articles [\n      {\n        url \"https://example.com/thin\"\n        title \"Anthropic ships Claude Code updates\"\n        source \"HN\"\n        snippet \"Read more.\"\n      }\n    ]\n  }\n  @@assert(kept_original, {{ this[0].title == \"Anthropic ships Claude Code updates\" }})\n}\n\n// Batch: URLs must not get crossed and content must not blend across articles.\ntest regression_batch_no_crosstalk {\n  functions [ImproveTitles]\n  args {\n    articles [\n      {\n        url \"https://example.com/a\"\n        title \"Meta releases Muse image model\"\n        source \"HN\"\n        snippet \"Meta made its Muse image model free on Instagram and WhatsApp, with API access.\"\n      }\n      {\n        url \"https://example.com/b\"\n        title \"vLLM news\"\n        source \"HN\"\n        snippet \"vLLM now integrates Hugging Face Transformers for production-grade inference serving.\"\n      }\n    ]\n  }\n  @@assert(both_returned, {{ this|list|length == 2 }})\n  @@assert(urls_distinct, {{ this[0].url != this[1].url }})\n  @@assert(no_blend, {{ \"Muse\" not in this[1].title }})\n}\n",
    "generators.baml": "generator python {\n  output_type \"python/pydantic\"\n  output_dir \"../\"\n  version \"0.223.0\"\n}\n",
    "score.baml": "class ScoredArticle {\n  url string\n  score int @description(\"1-100 developer-actionability rating\")\n}\n\nfunction ScoreArticles(articles: ArticleInput[]) -> ScoredArticle[] {\n  client Nvidia\n  prompt #\"\n    {{ _.role(\"system\") }}\n    You are a senior editorial analyst at a developer news platform. You rate articles on how much they help someone building with AI. You are precise and consistent, and when something is thin you say so with a low number.\n\n    {{ _.role(\"user\") }}\n    Score every article 1-100.\n\n    FIRST — IS IT IN SCOPE?\n    In scope: AI, ML, LLMs, foundation models, and the tools and infrastructure developers use to build with them.\n    Everything else scores 1-14 — stop there, do not read the rest of this guide: crypto/web3 (even when the post says \"agents\"), general programming (editors, parsers, version control, data structures, memory management), non-AI open source, security and formal verification with no AI component, classic ML/statistics tutorials (tree models, regression, tabular features), chip packaging and supply chain, regulation, politics, lawsuits, corporate drama, funding and hiring.\n\n    THEN — HOW MUCH DOES IT GIVE A BUILDER?\n    Two things decide the number:\n      EVIDENCE — what is actually shown? Runnable code, downloadable weights, a measured result with its method stated, or concrete steps a reader can copy. A number in a headline with no method behind it is a claim, not evidence — discount it hard, and the bigger the claim the harder.\n      REACH — how many people building with AI does it change something for? A frontier release or a runtime everyone uses is high. A weekend project, demo, or niche integration is low.\n\n    BANDS\n    Absolute, not relative to this batch. Every example below is a real item, correctly scored.\n\n    90-100 — Strong evidence, high reach. Frontier or open-weight releases you can run today, landmark results. Rare: a handful a month. 97+ is genuinely field-moving.\n      97  \"Kimi K3: Open Frontier Intelligence\" [Moonshot AI] — open 3T-class weights, frontier claims, downloadable.\n\n    80-89 — Real technical substance from a credible source, usable today. Also where a practitioner writeup lands when the technique is spelled out and reusable, first-party or not.\n      88  \"vLLM integrates Hugging Face Transformers for production-grade inference\" [HF Blog] — official integration, removes porting work for every model author.\n      85  \"TurboPrefill: 2.7x faster than llama.cpp Pipeline Parallel on Llama-3-70B\" [HN, 240 points] — upstream PR, stated hardware, measured speedup.\n      85  \"Optimizing Claude 3 Code's System Prompt for Efficiency and Output Quality\" [AI Hero] — third party, but the method is concrete and a reader can apply it.\n      82  \"Qwen3.6-27B KV Cache Quantization in vLLM: Accuracy, Memory, and Speed\" [Kaitchup] — measured comparison a reader can rerun.\n\n    70-79 — Useful but narrow, or well-made with modest novelty. Community writeups, series posts, and think pieces that leave a builder with something belong here.\n      74  \"Running Gemma 4 26B at 5 tokens/sec on a 13-year-old Xeon with no GPU\" [HN] — reproducible with exact flags, but narrow.\n      72  \"We measured agent token cost across 40 repos before picking a context strategy\" [Eng blog] — written for founders and leads, not the coder, but real data with a stated method and a decision it drove, selling nothing.\n      70  \"Set Up a $0 Cloud VM to Run Your Hermes Agent (Part 1)\" [AI Weekender] — serial newsletter post, but the steps work.\n      70  \"Why Human Language is the New Code (and How to Write It)\" [Substack] — think piece, worth a builder's time.\n      70  \"Orchestrating agents just got 10x easier, check out Temporal\" [x.com] — social post, but a real tool behind it.\n\n    55-69 — Minor tools, incremental product news, competent commentary, demos.\n      65  \"Ollama announces support for open models\" [HN] — real but small announcement, little to act on.\n      62  \"What 18 agent-built PRs cost us in context tokens\" [Vendor blog] — measured from their own sessions with the method stated, and it names a real line item, but it is a pitch for their product: the numbers carry it this far, the pitch holds it here.\n\n    35-54 — Unverified solo projects, marketing and landing pages, big numbers with no method.\n      45  \"LLMrPro: free LLM balancer combines local machines with cloud fallback\" [HN, 4 points, 0 comments] — unknown solo repo in a crowded category, and nobody read it.\n      35  \"SigMap cuts prompt count by 49% across 90 coding tasks\" [HN, 3 points, 1 comment] — landing page, extraordinary numbers, no method or repo.\n\n    15-34 — Slop, SEO bait, advocacy and campaign pages, manifestos, content-free.\n\n    1-14 — Out of scope only. An in-scope article never goes below 15: this band means \"wrong subject\", not \"bad\".\n\n    RULES\n    - A first-party release post on a major lab's own domain (openai.com, anthropic.com, deepmind.google, mistral.ai, kimi.com, ai.meta.com, qwen.ai, huggingface.co/blog, an official model card) never scores below 70. Aggregators retitle these into something that reads like a rewrite — judge the release, not the headline someone put on it.\n    - A piece written for founders or tech leads — someone deciding what their team builds with, not writing the code — is in scope, judged on the same EVIDENCE bar as everything else: data with a stated method, a named decision it informs, or steps someone can follow. One that clears it lands 55-72. A polished piece with only an argument behind it still caps at 40, as do pure careers, business strategy, funding, and hiring. A vendor piece that is really a pitch for the author's own product is discounted hard even when it carries numbers. \"The model is the brain, everything else is the desk\" is a metaphor, not evidence.\n    - A proposed spec, standard, or protocol with no users beyond its author caps at 70, even with a reference implementation. Anyone can publish a spec; adoption is what makes one matter.\n    - Empty snippet means you are judging a title alone → cap 70.\n    - Score against the whole field, not against the others in this batch. A weak batch produces low scores; that is the correct outcome.\n    - Topic is never a bonus. Local inference, quantization, privacy, on-device, and token cost are common subjects, not merit. A shallow post about local inference scores below a rigorous post about anything else.\n    - Trust tag: high +3, low -3, applied after the band is chosen. It breaks ties; it does not move an article between bands.\n    - Traction, when given, is how the public actually received the item where it was posted, and it is evidence about REACH — the one thing a title cannot fake. A submission sitting at single-digit points and no comments is a post nobody read: it caps at 45 regardless of how the title is written, and \"Show HN\"-style self-promotion there caps at 35. Strong traction (hundreds of points, a live discussion) confirms reach; it does not add evidence, so it never lifts a thin item past 70 on its own. No traction field means the source has no such signal — judge on evidence alone, do not assume either way.\n    - Use the whole range. 74, 68, and 52 are real scores. Most items are not 90s: if you are about to give a batch of five four scores above 85, you have stopped discriminating. Re-read the bands and place each one absolutely.\n\n    Articles:\n    {% for a in articles %}\n    {{ loop.index }}. [{{ a.source }}] \"{{ a.title }}\" - {{ a.url }}{% if a.trust %} [trust: {{ a.trust }}]{% endif %}{% if a.traction %} [traction: {{ a.traction }}]{% endif %}\n    {% if a.snippet %}   {{ a.snippet }}{% else %}   (no content available){% endif %}\n    {% endfor %}\n\n    {{ ctx.output_format }}\n  \"#\n}\n\ntest score_frontier_release {\n  functions [ScoreArticles]\n  args {\n    articles [\n      {\n        url \"https://www.kimi.com/blog/kimi-k3\"\n        title \"Kimi K3: Open Frontier Intelligence\"\n        source \"Moonshot AI\"\n        snippet \"Kimi K3 is the world's first open 3T-class model - frontier performance across coding, knowledge work, and reasoning.\"\n        trust \"medium\"\n      }\n    ]\n  }\n}\n\ntest score_out_of_scope {\n  functions [ScoreArticles]\n  args {\n    articles [\n      {\n        url \"https://x.com/NEARProtocol/status/2076729054632231274\"\n        title \"NEAR Launches General Availability of Confidential Intents via 1Click Swap API for Developer Integration\"\n        source \"Aligned News\"\n        snippet \"NEAR released Confidential Intents for general use through its 1Click Swap API.\"\n        trust \"medium\"\n      }\n    ]\n  }\n}\n\n// Separates practitioner content from advocacy. The newsletter walkthrough has\n// steps a reader can follow and should clear 65; the campaign page has nothing\n// technical and stays below 35.\ntest score_practitioner_vs_advocacy {\n  functions [ScoreArticles]\n  args {\n    articles [\n      {\n        url \"https://aiweekender.substack.com/p/set-up-a-0-cloud-vm-to-run-your-hermes\"\n        title \"Set Up a $0 Cloud VM to Run Your Hermes Agent (Part 1)\"\n        source \"AI Weekender\"\n        snippet \"This post is the first in a series. It details setting up a free, always-on Linux virtual machine. This VM will host a Hermes agent.\"\n        trust \"medium\"\n      }\n      {\n        url \"https://righttointelligence.org/\"\n        title \"Protect your right to run local AI\"\n        source \"Hacker News\"\n        snippet \"A campaign page advocating the right to run local AI. It calls for protecting the ability to run models on your own hardware.\"\n        trust \"medium\"\n        traction \"18 points, 6 comments on Hacker News\"\n      }\n    ]\n  }\n}\n\n// Founder-audience is in scope. The piece with measured data and a decision\n// behind it clears the threshold; the polished argument with nothing to act on\n// stays at or under 40; a vendor post that is really a product pitch lands in\n// the 55-69 band on the strength of its numbers but no higher.\ntest score_founder_audience {\n  functions [ScoreArticles]\n  args {\n    articles [\n      {\n        url \"https://example.com/blog/agent-token-cost-study\"\n        title \"We measured agent token cost across 40 repos before picking a context strategy\"\n        source \"Engineering blog\"\n        snippet \"Over six weeks we logged context-token usage for coding agents across 40 internal repos, with the measurement method and per-repo numbers. Here is how it shaped the retrieval approach we chose.\"\n        trust \"medium\"\n      }\n      {\n        url \"https://example.com/blog/why-agents-change-the-org\"\n        title \"Why AI agents change how you should structure your engineering org\"\n        source \"Substack\"\n        snippet \"A case that agents shift the unit of work from the team to the individual, and what that means for how founders should plan headcount.\"\n        trust \"medium\"\n      }\n      {\n        url \"https://vendor.example.com/blog/stop-the-context-tax\"\n        title \"What 18 agent-built PRs cost us in context tokens\"\n        source \"Vendor blog\"\n        snippet \"Each agent-built PR in our codebase averaged $65 in context-token overhead, peaking near 975k tokens. Our semantic navigation layer cuts that.\"\n        trust \"medium\"\n      }\n    ]\n  }\n}\n\n// Regression: a big percentage in a title with nothing behind it must not beat\n// a measured result. Expect the landing page well below the benchmark post.\ntest score_unverified_claim_vs_measured {\n  functions [ScoreArticles]\n  args {\n    articles [\n      {\n        url \"https://sigmap.io/\"\n        title \"SigMap cuts prompt count by 49% across 90 coding tasks\"\n        source \"Hacker News\"\n        snippet \"SigMap cuts prompt count by 49.2% on 90 coding tasks. It reduces token usage by 97% and runs offline with zero dependencies.\"\n        trust \"medium\"\n        traction \"3 points, 1 comments on Hacker News\"\n      }\n      {\n        url \"https://github.com/ggml-org/llama.cpp/pull/24219\"\n        title \"TurboPrefill: 2.7x faster than llama.cpp Pipeline Parallel on Llama-3-70B\"\n        source \"Hacker News\"\n        snippet \"TurboPrefill implements intra-prompt pipeline scheduling for multi-GPU prefill. On Llama-3-70B it runs 2.7x faster than llama.cpp pipeline parallel.\"\n        trust \"medium\"\n        traction \"240 points, 96 comments on Hacker News\"\n      }\n    ]\n  }\n}\n\n// Regression for the failure this rubric's traction rule exists to fix: an\n// unread Show HN repo and a lab release, judged on the same title-shaped\n// evidence. Before traction was passed through, batches like this came back\n// with both in the 90s. Expect the repo in the 35-54 band and the release well\n// clear of it.\ntest score_unread_repo_vs_lab_release {\n  functions [ScoreArticles]\n  args {\n    articles [\n      {\n        url \"https://github.com/Gysho/LLMrPro\"\n        title \"Free LLM balancer combines multiple local inference machines with cloud fallback\"\n        source \"Hacker News\"\n        snippet \"LLMrPro balances requests across local inference machines and falls back to the cloud.\"\n        trust \"medium\"\n        traction \"4 points, 0 comments on Hacker News\"\n      }\n      {\n        url \"https://www.anthropic.com/news/claude-sonnet-5\"\n        title \"Claude Sonnet 5: More agentic model with planning and tool use\"\n        source \"Hacker News\"\n        snippet \"Claude Sonnet 5 is available today across the API, with stronger planning and tool use.\"\n        trust \"medium\"\n        traction \"612 points, 341 comments on Hacker News\"\n      }\n    ]\n  }\n}\n",
    "shared.baml": "// Shared types used by multiple BAML functions.\n\nenum ArticleCategory {\n  Models\n  Dev\n  Research\n}\n\nenum ArticleKind {\n  Repo         // GitHub/GitLab repository\n  Paper        // Academic paper, preprint, technical report\n  Model        // Model card or model release page\n  Blog         // Developer blog post, tutorial, how-to, opinion piece\n  Product      // Product launch page or product website\n  Announcement // Official release post from a major AI lab\n}\n\n// Used as input to ScoreArticles, ImproveTitles.\n// Mirrors the fields the existing formatArticles() helper emits.\nclass ArticleInput {\n  url string\n  title string\n  source string\n  snippet string? @description(\"First ~200 chars of the article content, if any\")\n  trust string? @description(\"\\\"high\\\" | \\\"medium\\\" | \\\"low\\\" - source trust tag\")\n  traction string? @description(\"How the item was received where it was posted, e.g. \\\"7 points, 1 comments on Hacker News\\\". Absent for sources with no public reception signal.\")\n}\n",
}

def get_baml_files():
    return _file_map